1	<template>
2	    <Page @navigatedTo="onNavigatedTo">
3	        <ActionBar title="Health" />
4	        <ScrollView>
5	            <StackLayout class="p-6">
6	                <Label :text="statusLine" class="text-base mb-4" textWrap="true" />
7	                <Button text="Request Access" @tap="onRequestAccess" :isEnabled="!isRequesting" class="mb-3" />
8	                <Button text="Log 500 Steps" @tap="onLogSteps" :isEnabled="canLogSteps" class="mb-8" />
9	                <Label text="Last 7 Days" class="text-lg font-bold mb-2" />
10	                <StackLayout v-if="isGranted">
11	                    <Label
12	                        v-for="(day, index) in days"
13	                        :key="index"
14	                        :text="day.text"
15	                        :class="day.isToday ? 'font-bold mb-1' : 'mb-1'"
16	                        textWrap="true"
17	                    />
18	                </StackLayout>
19	                <Label v-else text="Health access needed" class="text-gray-500" textWrap="true" />
20	            </StackLayout>
21	        </ScrollView>
22	    </Page>
23	</template>
24	
25	<script setup lang="ts">
26	import { ref, computed } from 'vue'
27	import { Utils } from '@nativescript/core'
28	
29	const WEEKDAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']
30	const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']
31	
32	type DayRow = {
33	    text: string
34	    isToday: boolean
35	}
36	
37	const healthStore = HKHealthStore.new()
38	const stepType = HKObjectType.quantityTypeForIdentifier(HKQuantityTypeIdentifierStepCount)
39	
40	const authStatus = ref<HKAuthorizationStatus>(HKAuthorizationStatus.NotDetermined)
41	const errorText = ref('')
42	const isRequesting = ref(false)
43	const isSaving = ref(false)
44	const days = ref<DayRow[]>([])
45	
46	const isGranted = computed(() => authStatus.value === HKAuthorizationStatus.SharingAuthorized)
47	const isDenied = computed(() => authStatus.value === HKAuthorizationStatus.SharingDenied)
48	const canLogSteps = computed(() => isGranted.value && !isSaving.value)
49	
50	const statusLine = computed(() => {
51	    if (errorText.value) {
52	        return errorText.value
53	    }
54	    if (isGranted.value) {
55	        return 'Health access: granted'
56	    }
57	    if (isDenied.value) {
58	        return 'Health access: denied'
59	    }
60	    return 'Health access: not requested'
61	})
62	
63	function formatDay(date: Date): string {
64	    return `${WEEKDAYS[date.getDay()]} ${MONTHS[date.getMonth()]} ${date.getDate()}`
65	}
66	
67	function startOfDay(date: Date): Date {
68	    const result = new Date(date)
69	    result.setHours(0, 0, 0, 0)
70	    return result
71	}
72	
73	function addDays(date: Date, amount: number): Date {
74	    const result = new Date(date)
75	    result.setDate(result.getDate() + amount)
76	    return result
77	}
78	
79	function refreshAuthStatus() {
80	    authStatus.value = healthStore.authorizationStatusForType(stepType)
81	}
82	
83	function queryDailyTotal(dayStart: Date, dayEnd: Date): Promise<number> {
84	    return new Promise((resolve) => {
85	        const predicate = HKQuery.predicateForSamplesWithStartDateEndDateOptions(
86	            dayStart,
87	            dayEnd,
88	            HKQueryOptions.StrictStartDate | HKQueryOptions.StrictEndDate
89	        )
90	        const query = HKStatisticsQuery.alloc().initWithQuantityTypeQuantitySamplePredicateOptionsCompletionHandler(
91	            stepType,
92	            predicate,
93	            HKStatisticsOptions.CumulativeSum,
94	            (_query, result, error) => {
95	                if (error || !result) {
96	                    resolve(0)
97	                    return
98	                }
99	                const sum = result.sumQuantity()
100	                resolve(sum ? sum.doubleValueForUnit(HKUnit.countUnit()) : 0)
101	            }
102	        )
103	        healthStore.executeQuery(query)
104	    })
105	}
106	
107	async function loadLast7Days() {
108	    const today = startOfDay(new Date())
109	    const dayStarts = Array.from({ length: 7 }, (_, i) => addDays(today, -i))
110	    const totals = await Promise.all(dayStarts.map((dayStart) => queryDailyTotal(dayStart, addDays(dayStart, 1))))
111	    const results: DayRow[] = dayStarts.map((dayStart, i) => {
112	        const stepsText = Math.round(totals[i]).toLocaleString('en-US')
113	        const suffix = i === 0 ? ' (today)' : ''
114	        return {
115	            text: `${formatDay(dayStart)} — ${stepsText} steps${suffix}`,
116	            isToday: i === 0
117	        }
118	    })
119	    Utils.executeOnMainThread(() => {
120	        days.value = results
121	    })
122	}
123	
124	function onNavigatedTo() {
125	    errorText.value = ''
126	    refreshAuthStatus()
127	    if (isGranted.value) {
128	        loadLast7Days()
129	    }
130	}
131	
132	function onRequestAccess() {
133	    if (isRequesting.value) {
134	        return
135	    }
136	    errorText.value = ''
137	    if (!HKHealthStore.isHealthDataAvailable()) {
138	        errorText.value = 'Health data is not available on this device'
139	        return
140	    }
141	    isRequesting.value = true
142	    const shareTypes = NSSet.setWithObject<HKSampleType>(stepType)
143	    const readTypes = NSSet.setWithObject<HKObjectType>(stepType)
144	    healthStore.requestAuthorizationToShareTypesReadTypesCompletion(shareTypes, readTypes, (success, error) => {
145	        Utils.executeOnMainThread(() => {
146	            isRequesting.value = false
147	            if (!success && error) {
148	                errorText.value = error.localizedDescription
149	            }
150	            refreshAuthStatus()
151	            if (isGranted.value) {
152	                loadLast7Days()
153	            }
154	        })
155	    })
156	}
157	
158	function onLogSteps() {
159	    if (isSaving.value || !isGranted.value) {
160	        return
161	    }
162	    errorText.value = ''
163	    isSaving.value = true
164	    const quantity = HKQuantity.quantityWithUnitDoubleValue(HKUnit.countUnit(), 500)
165	    const now = new Date()
166	    const sample = HKQuantitySample.quantitySampleWithTypeQuantityStartDateEndDate(stepType, quantity, now, now)
167	    healthStore.saveObjectWithCompletion(sample, (success, error) => {
168	        Utils.executeOnMainThread(() => {
169	            isSaving.value = false
170	            if (success) {
171	                loadLast7Days()
172	            } else if (error) {
173	                errorText.value = error.localizedDescription
174	            }
175	        })
176	    })
177	}
178	</script>
